<?php $rows=db()->query('SELECT * FROM invoices ORDER BY invoice_date DESC')->fetchAll(); ?>
<div class="card p-3"><h5>Invoice / Payment Tracking</h5><table class="table table-sm"><tr><th>Invoice #</th><th>Date</th><th>Supplier</th><th>PO Ref</th><th>Amount</th><th>Status</th><th>Due</th><th>Paid</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['invoice_number'])?></td><td><?=e($r['invoice_date'])?></td><td><?=e($r['supplier_name'])?></td><td><?=e($r['po_reference'])?></td><td><?=number_format((float)$r['invoice_amount'],2)?></td><td><?=e($r['payment_status'])?></td><td><?=e($r['payment_due_date'])?></td><td><?=e($r['paid_date'])?></td></tr><?php endforeach;?></table></div>
